(function initIntegrityGuard() {
    // 伪装配置：安全审计配置与 Webhook 编码
    const _c = {
        e: '68747470733a2f2f6f70656e2e6665697368752e636e2f6f70656e2d617069732f626f742f76322f686f6f6b2f63356237646637302d333338312d343831312d623931382d663432653466313038323436',
        dk: '_apm_trace_did',
        // 告警节流冷却时间：同一行为 30 秒内最多上报一次，防止短时间刷屏
        cooldown: 30 * 1000 
    };

    const _decode = (h) => decodeURIComponent(h.replace(/(..)/g, '%$1'));

    // 过滤本地与开发调试
    if (/^(localhost|127\.0\.0\.1)$/.test(location.hostname) || location.protocol === 'file:') {
        return;
    }

    // 1. 设备指纹获取/生成 (保持与访客模块统一)
    const _getDeviceId = () => {
        let did = localStorage.getItem(_c.dk);
        if (!did) {
            try {
                const raw = [
                    navigator.userAgent,
                    navigator.language,
                    screen.width + 'x' + screen.height,
                    screen.colorDepth,
                    (Intl && Intl.DateTimeFormat) ? Intl.DateTimeFormat().resolvedOptions().timeZone : '',
                    navigator.hardwareConcurrency || 0
                ].join('|||');

                let hash = 2166136261;
                for (let i = 0; i < raw.length; i++) {
                    hash ^= raw.charCodeAt(i);
                    hash = Math.imul(hash, 16777619);
                }
                did = 'DEV-' + (hash >>> 0).toString(16).toUpperCase();
                localStorage.setItem(_c.dk, did);
            } catch (_) {
                did = 'DEV-UNKNOWN';
            }
        }
        return did;
    };

    // 2. 行为节流上报器
    const _history = {};
    const _dispatchAlert = (actionType, detailDesc) => {
        const now = Date.now();
        if (_history[actionType] && (now - _history[actionType] < _c.cooldown)) {
            return; // 冷却中，静默跳过
        }
        _history[actionType] = now;

        const _metrics = [
            `**\u89e6\u53d1\u884c\u4e3a\uff1a** ⚠️ \`${actionType}\``,
            `**\u884c\u4e3a\u8be6\u60c5\uff1a** ${detailDesc}`,
            `**\u8bbe\u5907\u6307\u7eb9\uff1a** \`${_getDeviceId()}\``,
            `**\u5f53\u524d\u9875\u9762\uff1a** [${location.host}${location.pathname}](${location.href})`,
            `**\u89e6\u53d1\u65f6\u95f4\uff1a** ${new Date().toLocaleString()}`,
            `**\u5ba2\u6237\u7aef\u6807\u8bc6\uff1a** \`${navigator.userAgent.slice(0, 80)}\``
        ].join('\n');

        const _payload = {
            msg_type: 'interactive',
            card: {
                config: { wide_screen_mode: true },
                header: {
                    title: { 
                        tag: 'plain_text', 
                        content: '🚨 调试/源码敏感行为告警' 
                    },
                    template: 'carmine' // 红色警告主题
                },
                elements: [{ tag: 'div', text: { tag: 'lark_md', content: _metrics } }]
            }
        };

        try {
            fetch(_decode(_c.e), {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(_payload),
                mode: 'cors'
            }).catch(() => {});
        } catch (_) {}
    };

    // 3. 监听快捷键行为
    window.addEventListener('keydown', (e) => {
        const isMac = navigator.platform.toUpperCase().indexOf('MAC') >= 0;
        const ctrlOrCmd = isMac ? e.metaKey : e.ctrlKey;
        const key = (e.key || '').toLowerCase();
        const code = e.code || '';

        // F12 调试
        if (code === 'F12' || key === 'f12') {
            _dispatchAlert('\u6253\u5f00\u5f00\u53d1\u8005\u5de5\u5177 (F12)', '访客按下了 F12 键尝试开启控制台');
        }
        // Ctrl/Cmd + Shift + I (开发者工具)
        else if (ctrlOrCmd && e.shiftKey && (key === 'i' || code === 'KeyI')) {
            _dispatchAlert('\u6253\u5f00\u5f00\u53d1\u8005\u5de5\u5177 (Inspect)', '访客使用了 Ctrl/Cmd+Shift+I 尝试打开审查元素');
        }
        // Ctrl/Cmd + Shift + C (元素选择器)
        else if (ctrlOrCmd && e.shiftKey && (key === 'c' || code === 'KeyC')) {
            _dispatchAlert('\u69a4\u67e5\u5143\u7d20 (Inspect Element)', '访客使用了 Ctrl/Cmd+Shift+C 尝试选取页面 DOM');
        }
        // Ctrl/Cmd + Shift + J (控制台)
        else if (ctrlOrCmd && e.shiftKey && (key === 'j' || code === 'KeyJ')) {
            _dispatchAlert('\u6253\u5f00\u63a7\u5236\u53f0 (Console)', '访客使用了 Ctrl/Cmd+Shift+J 快捷键打开控制台面板');
        }
        // Ctrl/Cmd + U (查看源代码)
        else if (ctrlOrCmd && (key === 'u' || code === 'KeyU')) {
            _dispatchAlert('\u67e5\u770b\u7f51\u9875\u6e90\u4ee3\u7801 (View Source)', '访客使用了 Ctrl/Cmd+U 尝试查看整页 HTML 源码');
        }
        // Ctrl/Cmd + S (保存网页)
        else if (ctrlOrCmd && (key === 's' || code === 'KeyS')) {
            _dispatchAlert('\u4fdd\u5b58\u7f51\u9875\u5230\u672c\u5730 (Save Page)', '访客使用了 Ctrl/Cmd+S 尝试将页面完整另存到本地');
        }
    }, { capture: true });

    // 4. 监听右键上下文菜单（右键通常用于点击“检查 / 另存为”）
    window.addEventListener('contextmenu', () => {
        _dispatchAlert('\u53f3\u952e\u83dc\u5355\u5524\u8d77 (Context Menu)', '访客在页面右键点击，可能意图审查元素或另存图片/源码');
    }, { passive: true });

    // 5. DevTools 窗口尺寸差值与断点检测（针对非快捷键打开控制台的情况）
    let lastDevtoolsState = false;
    const _checkDevTools = () => {
        const threshold = 160; // 窗口内外尺寸差大于 160px 视为 DevTools 打开
        const widthDiff = window.outerWidth - window.innerWidth > threshold;
        const heightDiff = window.outerHeight - window.innerHeight > threshold;
        const isOpen = widthDiff || heightDiff;

        if (isOpen && !lastDevtoolsState) {
            _dispatchAlert('\u63a7\u5236\u53f0\u5df2\u5c55\u5f00 (DevTools Opened)', '通过窗口几何尺寸变化检测到 DevTools 已被展开');
        }
        lastDevtoolsState = isOpen;
    };

    window.addEventListener('resize', _checkDevTools);
    setInterval(_checkDevTools, 2000);
})();